import{_ as t,o as n,c as o,a2 as r}from"./chunks/framework.e4u2V5E7.js";const p=JSON.parse('{"title":"Context Engineering","description":"Context Engineering reference documentation","frontmatter":{"title":"Context Engineering","description":"Context Engineering reference documentation"},"headers":[],"relativePath":"knowledge/context-engineering.md","filePath":"knowledge/context-engineering.md","lastUpdated":1784485118000}'),i={name:"knowledge/context-engineering.md"};function a(s,e,l,c,d,g){return n(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="context-engineering" tabindex="-1">Context Engineering <a class="header-anchor" href="#context-engineering" aria-label="Permalink to &quot;Context Engineering&quot;">​</a></h1><h1 id="context-engineering-—-knowledge-base" tabindex="-1">Context Engineering — Knowledge Base <a class="header-anchor" href="#context-engineering-—-knowledge-base" aria-label="Permalink to &quot;Context Engineering — Knowledge Base&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Context engineering is the discipline of designing, managing, and optimizing the information fed to LLMs to produce high-quality outputs. It encompasses context window management, retrieval strategies, conversation history, and context prioritization for building reliable AI systems.</p><h2 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h2><h3 id="context-window" tabindex="-1">Context Window <a class="header-anchor" href="#context-window" aria-label="Permalink to &quot;Context Window&quot;">​</a></h3><p>The context window is the maximum number of tokens an LLM can process in a single request, including system prompt, conversation history, retrieved context, and user input.</p><p><strong>Token budget allocation (typical):</strong></p><ul><li>System prompt: 10-15%</li><li>Retrieved context (RAG): 40-50%</li><li>Conversation history: 20-30%</li><li>User query + output space: 15-20%</li></ul><h3 id="context-types" tabindex="-1">Context Types <a class="header-anchor" href="#context-types" aria-label="Permalink to &quot;Context Types&quot;">​</a></h3><p><strong>System context</strong> — Persistent instructions defining model behavior, constraints, and output format. Loaded once per conversation.</p><p><strong>Conversational context</strong> — Message history from the current session. Provides continuity for multi-turn interactions.</p><p><strong>Retrieved context (RAG)</strong> — Documents or data fetched from external sources based on query relevance. Dynamic and query-specific.</p><p><strong>Tool context</strong> — Results from function calls or tool executions. Generated during the conversation.</p><p><strong>User context</strong> — User profile, preferences, and metadata that inform personalized responses.</p><h3 id="context-management-strategies" tabindex="-1">Context Management Strategies <a class="header-anchor" href="#context-management-strategies" aria-label="Permalink to &quot;Context Management Strategies&quot;">​</a></h3><p><strong>Sliding window</strong> — Keep the last N messages; drop oldest when context exceeds budget. Simple but loses early context.</p><p><strong>Summarization</strong> — Periodically summarize older conversation turns to reduce token count while preserving key information.</p><p><strong>Priority-based selection</strong> — Rank context pieces by relevance and importance; include only the highest-priority items.</p><p><strong>Hierarchical context</strong> — Layer context from general (system prompt) to specific (recent messages, retrieved documents).</p><h3 id="context-compression" tabindex="-1">Context Compression <a class="header-anchor" href="#context-compression" aria-label="Permalink to &quot;Context Compression&quot;">​</a></h3><p><strong>Extractive compression</strong> — Select and return the most relevant portions of documents without modification.</p><p><strong>Abstractive compression</strong> — Generate a condensed summary that captures key information from multiple sources.</p><p><strong>Query-specific filtering</strong> — Filter retrieved documents based on query terms, metadata, or semantic relevance.</p><h3 id="context-prioritization" tabindex="-1">Context Prioritization <a class="header-anchor" href="#context-prioritization" aria-label="Permalink to &quot;Context Prioritization&quot;">​</a></h3><p><strong>Relevance scoring</strong> — Rank context by semantic similarity to the query using embedding-based search.</p><p><strong>Recency weighting</strong> — More recent information may be more relevant; apply time-based decay to older context.</p><p><strong>Authority scoring</strong> — Trusted sources get higher priority; verified data ranks above unverified.</p><p><strong>Diversity control</strong> — Ensure context covers multiple perspectives; avoid redundant information from similar sources.</p><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><strong>Plan token budget carefully</strong> — Allocate specific token budgets for each context type; don&#39;t let any single section dominate</li><li><strong>Prioritize recent and relevant context</strong> — Sliding windows lose early context; use summarization or retrieval to preserve important information</li><li><strong>Compress conversation history</strong> — Summarize older turns into condensed context; keep the last 3-5 turns in full detail</li><li><strong>Use structured context format</strong> — Organize context with clear delimiters and labels; help the model distinguish between different information types</li><li><strong>Implement context relevance filtering</strong> — Don&#39;t dump all retrieved documents into context; filter by relevance score threshold</li><li><strong>Handle context overflow gracefully</strong> — When approaching token limits, truncate lower-priority context rather than failing</li><li><strong>Cache and reuse context</strong> — For repeated queries, cache retrieved context with TTL; avoid redundant retrieval</li><li><strong>Monitor context quality</strong> — Track which context sections contribute to good outputs; refine retrieval and prioritization</li></ol><h2 id="anti-patterns" tabindex="-1">Anti-Patterns <a class="header-anchor" href="#anti-patterns" aria-label="Permalink to &quot;Anti-Patterns&quot;">​</a></h2><ol><li><strong>Ignoring token limits</strong> — Sending context that exceeds the model&#39;s window causes truncation or errors; always stay within limits</li><li><strong>Including irrelevant context</strong> — Irrelevant documents confuse the model and waste tokens; filter aggressively</li><li><strong>Losing important early context</strong> — Sliding windows discard the first messages; system-critical information from early conversation may be lost</li><li><strong>Duplicating information across context sources</strong> — Same information in system prompt and retrieved context wastes tokens; deduplicate</li><li><strong>Treating all context equally</strong> — Not all information is equally important; prioritize based on relevance, recency, and authority</li><li><strong>Forgetting to update context</strong> — Stale context produces outdated responses; refresh retrieved context periodically</li><li><strong>Overstuffing context to &quot;help&quot;</strong> — More context doesn&#39;t always help; focused, relevant context outperforms comprehensive dumps</li><li><strong>Not handling multi-language context</strong> — Mixing Arabic and English context may confuse models; clearly label language and separate if needed</li></ol><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><ol><li><strong>Not tracking token usage</strong> — Blindly building context without counting tokens leads to overflow; always monitor token count per request</li><li><strong>Using only raw documents</strong> — Raw documents are verbose; extract and compress key information before including in context</li><li><strong>Ignoring conversation length</strong> — Long conversations accumulate context; implement automatic summarization or sliding window</li><li><strong>Including sensitive data unnecessarily</strong> — Only include PII or sensitive data when strictly necessary for the task</li><li><strong>Not testing with realistic context sizes</strong> — Development uses small contexts; production may have much larger; test at scale</li><li><strong>Forgetting system prompt tokens</strong> — System prompts are part of the context budget; large system prompts leave less room for user content</li><li><strong>Using wrong delimiter format</strong> — Inconsistent delimiters make it hard for models to parse context sections; use XML tags or markdown headers</li><li><strong>Not accounting for model-specific tokenization</strong> — Different models tokenize differently; a 4K token context may be 3K or 5K depending on the tokenizer</li></ol><h2 id="decision-guidelines" tabindex="-1">Decision Guidelines <a class="header-anchor" href="#decision-guidelines" aria-label="Permalink to &quot;Decision Guidelines&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Context Need</th><th>Strategy</th></tr></thead><tbody><tr><td>Multi-turn conversation</td><td>Sliding window (last 10 turns) + periodic summarization</td></tr><tr><td>Large document retrieval</td><td>Chunk documents, retrieve top-k by relevance, compress</td></tr><tr><td>Personalized responses</td><td>User profile context + preference history</td></tr><tr><td>Tool-heavy workflows</td><td>Include only tool results relevant to current step</td></tr><tr><td>Multi-language context</td><td>Label language, separate sections, test with both languages</td></tr><tr><td>Cost-sensitive features</td><td>Minimize context length, cache aggressively, use smaller models</td></tr></tbody></table><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li>Anthropic Context Engineering: <a href="https://docs.anthropic.com/" target="_blank" rel="noreferrer">https://docs.anthropic.com/</a></li><li>OpenAI Context Window Guide: <a href="https://platform.openai.com/docs/" target="_blank" rel="noreferrer">https://platform.openai.com/docs/</a></li><li>LangChain Context Management: <a href="https://js.langchain.com/" target="_blank" rel="noreferrer">https://js.langchain.com/</a></li><li>Vercel AI SDK Context Patterns: <a href="https://sdk.vercel.ai/" target="_blank" rel="noreferrer">https://sdk.vercel.ai/</a></li><li>&quot;Building LLM Applications&quot; — Various community resources</li></ul><h2 id="practical-notes" tabindex="-1">Practical Notes <a class="header-anchor" href="#practical-notes" aria-label="Permalink to &quot;Practical Notes&quot;">​</a></h2><ul><li><strong>Token counting:</strong> Use <code>tiktoken</code> or provider-specific tokenizers to count tokens accurately before sending requests</li><li><strong>Supabase for context storage:</strong> Store conversation history, user preferences, and cached context in Supabase tables</li><li><strong>Arabic tokenization:</strong> Arabic text often tokenizes to more tokens than English equivalent; budget extra tokens for Arabic content</li><li><strong>Monitoring:</strong> Track context size, retrieval quality, and output quality metrics; alert on degraded context quality</li><li><strong>Iterative refinement:</strong> Context engineering is experimental; test different context strategies and measure output quality</li></ul><h2 id="related-topics" tabindex="-1">Related Topics <a class="header-anchor" href="#related-topics" aria-label="Permalink to &quot;Related Topics&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/knowledge/">Knowledge Base</a> for all reference documents.</p>',43)])])}const m=t(i,[["render",a]]);export{p as __pageData,m as default};
